                val borderWidth: Float,
            )
            /**
             * @property disabled uploaders: opacity › disabled. Applies to all variants. Opacity as a 0-1 Compose alpha (Figma stores this value as 0-100).
             */
            @androidx.compose.runtime.Immutable
            data class Opacity(
                val disabled: Float,
            )
        }
    }
}

